const REMOTE_AGENT_PROTOCOL_VERSION=3,REMOTE_CALLBACK_NOT_PENDING=`CALLBACK_NOT_PENDING`,REMOTE_CALLBACK_NOT_PENDING_MESSAGE=`Session callback not pending.`,REMOTE_AGENT_PROTOCOL_MISMATCH=`REMOTE_AGENT_PROTOCOL_MISMATCH`,UNVERSIONED_REMOTE_AGENT_PROTOCOL=1,V26_INPUT_REMOTE_AGENT_PROTOCOL=2,CALLBACK_PROTOCOL_QUERY=`eveRemoteProtocol`;function callbackUrlForProtocol(e,t){let n=new URL(e);return n.searchParams.set(CALLBACK_PROTOCOL_QUERY,String(t)),n.toString()}function readCallbackProtocol(e){let t=URL.parse(e)?.searchParams.get(CALLBACK_PROTOCOL_QUERY);if(t!=null&&/^[1-9]\d*$/.test(t))return Number(t)}function servesRemoteAgentCaller(e){return Number.isSafeInteger(e)&&e>=2&&e<=3}function formatEarlierRemoteCallerInputError(e){return`This session needs a person's answer, but its caller's deployment speaks eve remote agent protocol ${String(e)}, which can't receive approvals, questions, or sign-ins from protocol 3. Upgrade the caller's deployment to the same eve release.`}function formatEarlierRemoteChildStreamError(e){return`Remote agent "${e.name}" speaks eve remote agent protocol ${String(e.childVersion)}, so this deployment can't follow its stream. Its result still arrives. Upgrade both deployments to the same eve release to follow it.`}function readRemoteAgentProtocolVersion(e){return typeof e==`number`?e:1}function formatRemoteAgentProtocolMismatch(e){return`Remote agent "${e.name}" speaks eve remote agent protocol ${String(e.receiverVersion)}, but this deployment speaks protocol 3. Upgrade both deployments to the same eve release.`}export{REMOTE_AGENT_PROTOCOL_MISMATCH,REMOTE_AGENT_PROTOCOL_VERSION,REMOTE_CALLBACK_NOT_PENDING,REMOTE_CALLBACK_NOT_PENDING_MESSAGE,UNVERSIONED_REMOTE_AGENT_PROTOCOL,V26_INPUT_REMOTE_AGENT_PROTOCOL,callbackUrlForProtocol,formatEarlierRemoteCallerInputError,formatEarlierRemoteChildStreamError,formatRemoteAgentProtocolMismatch,readCallbackProtocol,readRemoteAgentProtocolVersion,servesRemoteAgentCaller};